// specs/standardize-breadcrumb-behavior-across-tenant-scoped-screens.spec.ts
// Spec file — Standardize Breadcrumb Behavior Across Tenant-Scoped Screens
// Source: ui/artifacts/user-story-1338351.md (user-story-id: 1338351, no test cases — derived from AC)
// Generated by: ui-testcase-orchestrator (dry-run)
import { test, expect, Page, Browser } from '@playwright/test';
import { LoginPage } from '../pages/login.page';
import { MultiTenantDashboardPage } from '../pages/multi-tenant-dashboard.page';
import { ActivityReportPage } from '../pages/activity-report.page';
import { SitesPage } from '../pages/sites.page';
import { ManageDevicesPage } from '../pages/manage-devices.page';
import { config } from '../config/test-config';

const TENANT_ID     = '20251015091882397';
const LOGIN_MODE = (process.env.LOGIN_MODE ?? 'single').toLowerCase();
const USE_SINGLE_LOGIN = LOGIN_MODE === 'single';
const BREADCRUMB_PARALLEL = process.env.BREADCRUMB_PARALLEL === 'true';

test.describe('Standardize Breadcrumb Behavior Across Tenant-Scoped Screens', () => {
  // Single mode reuses one browser page and stays serial. Multiple mode is parallel-safe.
  test.describe.configure({ mode: USE_SINGLE_LOGIN ? 'serial' : (BREADCRUMB_PARALLEL ? 'parallel' : 'default') });

  let sharedPage: Page;
  let loginPage: LoginPage;
  let dashboardPage: MultiTenantDashboardPage;
  let activityReportPage: ActivityReportPage;
  let sitesPage: SitesPage;
  let manageDevicesPage: ManageDevicesPage;
  let initialTenantName = '';

  const initializePages = (page: Page) => {
    sharedPage = page;
    loginPage = new LoginPage(sharedPage);
    dashboardPage = new MultiTenantDashboardPage(sharedPage);
    activityReportPage = new ActivityReportPage(sharedPage);
    sitesPage = new SitesPage(sharedPage);
    manageDevicesPage = new ManageDevicesPage(sharedPage);
  };

  const loginAndSelectTenant = async () => {
    await loginPage.goto();
    await loginPage.fillUsername(config.username);
    await loginPage.fillPassword(config.password);
    await loginPage.clickSignIn();

    // Wait for the multi-tenant selection dialog to appear after login
    await dashboardPage.waitForMultiTenantDialog();

    // Select the first tenant from the dialog
    await dashboardPage.clickChooseTenantDropdown();
    await dashboardPage.selectFirstTenantOption();

    await dashboardPage.assertIsDashboard();
    initialTenantName = (await dashboardPage.getSelectedTenantName()).trim();
  };

  const ensureDashboardTenantContext = async () => {
    await sharedPage.goto(config.baseUrl + '#/multi-tenant/dashboard');
    await sharedPage.waitForTimeout(800); // allow SPA to decide whether to show tenant dialog

    // If the tenant selection dialog appeared (e.g. after a tenant switch in AC3), re-select via dialog
    const dialogVisible = await dashboardPage.isMultiTenantDialogVisible();
    if (dialogVisible) {
      await dashboardPage.clickChooseTenantDropdown();
      await dashboardPage.selectFirstTenantOption();
    } else {
      // No dialog — check header tenant and switch back via header if needed
      const currentTenant = await dashboardPage.getSelectedTenantName();
      if (initialTenantName && currentTenant.trim() !== initialTenantName) {
        await dashboardPage.switchHeaderTenantToFirstOption();
      }
    }

    await dashboardPage.assertIsDashboard();
  };

  if (USE_SINGLE_LOGIN) {
    test.beforeAll(async ({ browser }: { browser: Browser }) => {
      const page = await browser.newPage();
      initializePages(page);
      await loginAndSelectTenant();
    });

    test.beforeEach(async () => {
      await ensureDashboardTenantContext();
    });

    test.afterAll(async () => {
      await sharedPage.close();
    });
  } else {
    test.beforeEach(async ({ page }) => {
      initializePages(page);
      await loginAndSelectTenant();
      await ensureDashboardTenantContext();
    });
  }

  // Source: user-story-1338351.md | AC1 — Standard Breadcrumb Structure on Tenant-Scoped Pages
  test('AC1 — Activity Report breadcrumb shows Dashboard > Tenant Name > Activity Report', async () => {

    await test.step('Navigate to Activity Report via sidebar', async () => {
      console.log('▶ Navigate to Activity Report via sidebar');
      await dashboardPage.clickNavItem('Activity Report');
      await activityReportPage.waitForPage();
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac1-activity-report.png' });
    });

    await test.step('Assert breadcrumb structure is Dashboard > Tenant Name > Activity Report', async () => {
      console.log('▶ Assert breadcrumb structure is Dashboard > Tenant Name > Activity Report');
      await activityReportPage.assertBreadcrumb(initialTenantName);
      await expect(sharedPage).toHaveURL(/\/#\/multi-tenant\/service-activity-report/);
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac1-assertion.png' });
    });

  });

  // Source: user-story-1338351.md | AC2 — Breadcrumb Displays Tenant Name Not Tenant ID
  test('AC2 — Breadcrumb displays human-readable Tenant Name not numeric Tenant ID on Sites page', async () => {

    await test.step('Navigate to Sites via sidebar', async () => {
      console.log('▶ Navigate to Sites via sidebar');
      await dashboardPage.clickNavItem('Sites');
      await sitesPage.waitForPage();
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac2-sites.png' });
    });

    await test.step('Assert breadcrumb tenant segment shows name not ID', async () => {
      console.log('▶ Assert breadcrumb tenant segment shows name not ID');
      const tenantText = await sitesPage.getBreadcrumbTenantText();
      expect(tenantText).toBe(initialTenantName);
      expect(tenantText).not.toBe(TENANT_ID);
      expect(tenantText).not.toMatch(/^\d+$/); // must not be purely numeric
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac2-assertion.png' });
    });

  });

  // Source: user-story-1338351.md | AC3 — Breadcrumb Updates on Tenant Switch
  test('AC3 — Breadcrumb updates immediately when switching tenant via header dropdown', async () => {
    let switchedTenantName = '';

    await test.step('Navigate to Activity Report', async () => {
      console.log('▶ Navigate to Activity Report');
      await dashboardPage.clickNavItem('Activity Report');
      await activityReportPage.waitForPage();
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac3-before-switch.png' });
    });

    await test.step('Assert initial breadcrumb shows first tenant name', async () => {
      console.log('▶ Assert initial breadcrumb shows first tenant name');
      await activityReportPage.assertBreadcrumb(initialTenantName);
    });

    await test.step('Switch tenant via header dropdown', async () => {
      console.log('▶ Switch tenant via header dropdown');
      // Open header tenant combobox and pick the second visible option.
      await sharedPage.getByRole('combobox').first().click();
      const options = sharedPage.getByRole('option');
      const optionCount = await options.count();
      expect(optionCount).toBeGreaterThan(1);
      await options.nth(1).click();
      await sharedPage.waitForTimeout(1500); // allow breadcrumb to re-render after SPA tenant switch
      switchedTenantName = (await dashboardPage.getSelectedTenantName()).trim();
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac3-after-switch.png' });
    });

    await test.step('Assert breadcrumb tenant segment updates to second tenant name', async () => {
      console.log('▶ Assert breadcrumb tenant segment updates to second tenant name');
      const tenantText = await activityReportPage.getBreadcrumbTenantText();
      if (switchedTenantName) {
        expect(tenantText).toBe(switchedTenantName);
      }
      expect(tenantText).not.toBe(initialTenantName);
    });

  });

  // Source: user-story-1338351.md | AC4 — Breadcrumb Correct on Direct URL Navigation
  test('AC4 — Breadcrumb correctly resolves tenant context on direct URL navigation', async () => {

    await test.step('Navigate directly via URL to Manage Devices for selected tenant', async () => {
      console.log('▶ Navigate directly via URL to Manage Devices for selected tenant');
      await manageDevicesPage.goto();
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac4-direct-url.png' });
    });

    await test.step('Assert breadcrumb shows Dashboard > Tenant Name > Manage Devices', async () => {
      console.log('▶ Assert breadcrumb shows Dashboard > Tenant Name > Manage Devices');
      await manageDevicesPage.assertBreadcrumb(initialTenantName);
      await expect(sharedPage).toHaveURL(/\/#\/multi-tenant\/manage-devices/);
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac4-assertion.png' });
    });

  });

  // Source: user-story-1338351.md | AC5 — Breadcrumb Consistency Across All Tenant-Scoped Pages
  test('AC5 — Breadcrumb format is consistent across Activity Report, Sites, and Manage Devices', async () => {

    await test.step('Navigate to Activity Report and capture breadcrumb', async () => {
      console.log('▶ Navigate to Activity Report and capture breadcrumb');
      await dashboardPage.clickNavItem('Activity Report');
      await activityReportPage.waitForPage();
      const items = await activityReportPage.getBreadcrumbItems();
      expect(items).toHaveLength(3);
      expect(items[0]).toBe('Dashboard');
      expect(items[1]).toBe(initialTenantName);
      expect(items[2]).toBe('Activity Report');
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac5-activity-report.png' });
    });

    await test.step('Navigate to Sites and confirm breadcrumb format matches', async () => {
      console.log('▶ Navigate to Sites and confirm breadcrumb format matches');
      await dashboardPage.clickNavItem('Sites');
      await sitesPage.waitForPage();
      const items = await sitesPage.getBreadcrumbItems();
      expect(items).toHaveLength(3);
      expect(items[0]).toBe('Dashboard');
      expect(items[1]).toBe(initialTenantName);
      expect(items[2]).toBe('Sites');
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac5-sites.png' });
    });

    await test.step('Navigate to Manage Devices and confirm breadcrumb format matches', async () => {
      console.log('▶ Navigate to Manage Devices and confirm breadcrumb format matches');
      await dashboardPage.clickNavItem('Manage Devices');
      await manageDevicesPage.waitForPage();
      const items = await manageDevicesPage.getBreadcrumbItems();
      expect(items).toHaveLength(3);
      expect(items[0]).toBe('Dashboard');
      expect(items[1]).toBe(initialTenantName);
      expect(items[2]).toBe('Manage Devices');
      await sharedPage.screenshot({ path: 'test-results/screenshots/breadcrumb-ac5-manage-devices.png' });
    });

  });

});
